  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver korrekt minimumskravet (journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik), kravet om beskrivelse af den varige funktionsnedsættelse og epikrise/afslutningsbrev som udgangspunkt ved afsluttet behandling. Afvisningsfølgen stemmer med vejledningen. Ingen af rubrikkens materielle fejl begås: kravene præsenteres ikke som kumulative, og epikrise gøres ikke til et absolut krav."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: journalmateriale fra de nævnte behandlertyper, beskrivelse af den varige funktionsnedsættelse og epikrise/afslutningsbrev som udgangspunkt ved afsluttet behandling."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilken lægelig dokumentation ansøgningen skal indeholde, herunder når behandlingen er afsluttet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som bestemmelse, paragraf eller vejledningsafsnit. Det er kun almindelig tekst uden henvisninger."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret citerer ingen kilde, så kildernes gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen angivne kilder, så det kan ikke vurderes, om de understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle væsentlige udsagn har støtte i vejledningens afsnit 4.1 og SU-bekendtgørelsens § 37, stk. 1 og 3. Der er ingen tilføjede regler, betingelser eller tærskler."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Forbeholdet 'som udgangspunkt' er bevaret ved epikrise/afslutningsbrev. Rubrikkens forbehold om, at titlen ikke afgør tilstrækkeligheden, er ikke nævnt, men svaret påstår ikke det modsatte. Afvisningsfølgen er gengivet korrekt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: minimumskrav, tillæg ved afsluttet behandling og følge ved manglende dokumentation hænger logisk sammen."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal som minimum' for journalmaterialet og 'som udgangspunkt' for epikrise/afslutningsbrev svarer til kilden. 'Afviser' svarer til vejledningens formulering og gøres ikke mere absolut end kilden."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "yes",
      "reason": "Svaret siger, at dokumentationen som udgangspunkt også skal indeholde epikrise eller afslutningsbrev, når behandlingsforløbet er afsluttet."
    },
    "A32": {
      "label": "yes",
      "reason": "Svaret dækker, at dokumentationen som udgangspunkt også indeholder epikrise eller afslutningsbrev ved afsluttet behandling."
    }
  },
  "overall_notes": "Indholdsmæssigt korrekt og fuldstændigt svar, men uden kildehenvisning. C04 er derfor not_met, og C05 og C06 er not_assessable efter kildereglen. Svaret formulerer 'skal ... som udgangspunkt' en anelse stærkere end vejledningens 'vil ... som udgangspunkt', men udgangspunktsforbeholdet er bevaret, og det er ikke en væsentlig fejl."
}

